html:
{% set tenant = frappe.get_doc("Tenant", doc.tenant) if doc.tenant else None %}
{% set shop = frappe.get_doc("Airport Shop", doc.shop) if doc.shop else None %}
{% set contract = frappe.get_doc("Shop Contract", doc.contract) if doc.contract else None %}
{% set posted_on = frappe.utils.formatdate(doc.posting_date or frappe.utils.nowdate(), "MMM d, yyyy") %}
{% set period_from = frappe.utils.formatdate(doc.period_start, "MMM d, yyyy") if doc.period_start else "" %}
{% set period_to = frappe.utils.formatdate(doc.period_end, "MMM d, yyyy") if doc.period_end else "" %}
{% set amount_fmt = frappe.utils.fmt_money(doc.amount) %}

<style>
  :root {
    --fg: #111827;
    --muted: #6b7280;
    --line: #e5e7eb;
    --accent: #0ea5e9;
  }
  * { box-sizing: border-box; }
  body, html { margin:0; padding:0; font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, "Helvetica Neue", Arial, sans-serif; color: var(--fg); }
  .wrap { max-width: 780px; margin: 0 auto; padding: 24px; }
  .card { border: 1px solid var(--line); border-radius: 12px; padding: 22px; }
  .head { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
  .brand h1 { font-size: 20px; margin: 0 0 4px; letter-spacing: .3px; }
  .brand p { margin: 0; color: var(--muted); font-size: 12px; }
  .doc-meta { text-align: right; }
  .doc-meta h2 { margin: 0; font-size: 18px; }
  .doc-meta p { margin: 2px 0; color: var(--muted); font-size: 12px; }
  hr { border: 0; border-top: 1px solid var(--line); margin: 16px 0; }
  .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
  .sec h3 { margin: 0 0 8px; font-size: 13px; text-transform: uppercase; letter-spacing: .6px; color: var(--muted); }
  .kv { margin: 2px 0; font-size: 13px; }
  .kv b { color: var(--fg); }
  .pill { display: inline-block; padding: 2px 8px; font-size: 11px; border: 1px solid var(--line); border-radius: 999px; color: var(--muted); }
  .total { background: #f8fafc; border: 1px dashed var(--line); border-radius: 10px; padding: 14px; margin-top: 10px; }
  .total h2 { margin: 0; font-size: 22px; }
  .tfoot { display: flex; justify-content: space-between; align-items: center; margin-top: 26px; }
  .sign { text-align: right; font-size: 12px; color: var(--muted); }
  .terms { margin-top: 14px; color: var(--muted); font-size: 12px; line-height: 1.5; }
  .small { font-size: 12px; color: var(--muted); }
  .mono { font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace; }
</style>

<div class="wrap">
  <div class="card">
    <!-- Header -->
    <div class="head">
      <div class="brand">
        <h1>Airport Shop Management</h1>
        <p>Rent Receipt</p>
      </div>
      <div class="doc-meta">
        <h2 class="mono">{{ doc.name }}</h2>
        <p>Receipt Date: <b>{{ posted_on }}</b></p>
        {% if contract and contract.status %}<p>Status: <span class="pill">{{ contract.status }}</span></p>{% endif %}
      </div>
    </div>

    <hr>

    <!-- Parties & Shop -->
    <div class="grid">
      <div class="sec">
        <h3>Tenant Details</h3>
        <p class="kv"><b>{{ tenant.tenant_name if tenant else doc.tenant }}</b></p>
        {% if tenant and tenant.address %}<p class="small">{{ tenant.address }}</p>{% endif %}
        <p class="small">
          {% if tenant and tenant.email %}✉ {{ tenant.email }}{% endif %}
          {% if tenant and tenant.phone %} &nbsp; • &nbsp; ☎ {{ tenant.phone }}{% endif %}
        </p>
      </div>
      <div class="sec">
        <h3>Shop Details</h3>
        <p class="kv">
          <b>{{ shop.shop_name if shop and shop.shop_name else (shop.name if shop else doc.shop) }}</b>
        </p>
        <p class="small">
          {% if shop and shop.shop_number %}Shop No: <span class="mono">{{ shop.shop_number }}</span>{% endif %}
          {% if shop and shop.airport %} &nbsp; • &nbsp; Airport: <span class="mono">{{ shop.airport }}</span>{% endif %}
          {% if shop and shop.shop_type %} &nbsp; • &nbsp; Type: <span class="mono">{{ shop.shop_type }}</span>{% endif %}
          {% if shop and shop.area_sqft %} &nbsp; • &nbsp; Area: <span class="mono">{{ shop.area_sqft }} sqft</span>{% endif %}
        </p>
      </div>
    </div>

    <!-- Contract & Period -->
    <div class="grid" style="margin-top:10px;">
      <div class="sec">
        <h3>Contract</h3>
        <p class="kv">Contract No: <b class="mono">{{ doc.contract }}</b></p>
        {% if contract and contract.start_date and contract.end_date %}
          <p class="small">
            Term: {{ frappe.utils.formatdate(contract.start_date, "MMM d, yyyy") }} — {{ frappe.utils.formatdate(contract.end_date, "MMM d, yyyy") }}
          </p>
        {% endif %}
      </div>
      <div class="sec">
        <h3>Rent Period</h3>
        <p class="kv"><b>{{ period_from }}</b> to <b>{{ period_to }}</b></p>
        {% if doc.mode_of_payment %}<p class="small">Mode of Payment: <span class="mono">{{ doc.mode_of_payment }}</span></p>{% endif %}
        {% if doc.reference_no %}<p class="small">Reference No: <span class="mono">{{ doc.reference_no }}</span></p>{% endif %}
        {% if doc.reference_date %}<p class="small">Reference Date: {{ frappe.utils.formatdate(doc.reference_date, "MMM d, yyyy") }}</p>{% endif %}
      </div>
    </div>

    <div class="total">
  <div style="display:flex;align-items:center;justify-content:space-between;gap:16px;">
    <div>
      <div class="small">Amount Received</div>
      <h2>{{ amount_fmt }}</h2>
    </div>

    {% if frappe.db.exists("Shop Settings", "Shop Settings") %}
      {% set settings = frappe.get_doc("Shop Settings", "Shop Settings") %}
      {% if settings.default_rent_amount and doc.amount %}
        {% set rent_amt = (doc.amount | float) %}
        {% set default_amt = (settings.default_rent_amount | float) %}
        {% if rent_amt < default_amt %}
          <div class="small">
            Note: Amount is less than default rent ({{ frappe.utils.fmt_money(settings.default_rent_amount) }}).
          </div>
        {% endif %}
      {% endif %}
    {% endif %}
  </div>
</div>

    <!-- Footer -->
    <div class="tfoot">
      <div class="small">
        Generated on {{ frappe.utils.format_datetime(frappe.utils.now_datetime(), "MMM d, yyyy hh:mm a") }}.
      </div>
      <div class="sign">
        <div style="height:46px;"></div>
        <div>Authorized Signature</div>
      </div>
    </div>

    <div class="terms">
      <b>Terms & Notes:</b>
      <ol style="margin:6px 0 0 18px;">
        <li>This is a system-generated receipt for rent received for the mentioned period.</li>
        <li>All cheque/online payments are subject to realization.</li>
        <li>Please quote Receipt No. <span class="mono">{{ doc.name }}</span> for any correspondence.</li>
      </ol>
    </div>
  </div>
</div>
